package com.yjiyun.chatflows.runtime;
import com.yjiyun.chatflows.runtime.agent.*; import com.yjiyun.chatflows.runtime.api.RuntimeService; import com.yjiyun.chatflows.runtime.blueprint.*; import com.yjiyun.chatflows.runtime.security.*; import io.agentscope.core.agent.RuntimeContext; import io.agentscope.core.permission.*; import io.agentscope.core.tool.ToolBase; import java.nio.file.*; import java.util.*;
public final class RuntimeSelfTest {
 public static void main(String[] a)throws Exception{Path ws=Files.createTempDirectory("runtime-workspace");System.setProperty("agentscope.state.home",ws.resolve("state").toString());Files.writeString(ws.resolve("AGENTS.md"),"seed");Files.writeString(ws.resolve("SOUL.md"),"seed");Files.writeString(ws.resolve("tools.json"),"{\"mcpServers\":{}}");try(AgentFactory f=new AgentFactory(ws,new DeterministicModel())){InMemoryBlueprintRepository repo=new InMemoryBlueprintRepository();TenantToolPermissions permissions=new TenantToolPermissions();BlueprintProjector p=new BlueprintProjector(f.agent(),repo,permissions);RuntimeContextFactory contexts=new RuntimeContextFactory();AgentBlueprint v1=bp("bp-1",1,"tenant-a","agent-a","A-style");repo.stage(v1,"builder");RuntimeContext aCtx=contexts.create("tenant-a","alice","s1","agent-a");boolean blocked=false;try{p.projectPublished("tenant-a","alice","agent-a",aCtx);}catch(IllegalStateException e){blocked=true;}if(!blocked)throw new AssertionError("DRAFT projected");repo.publish("bp-1","tenant-a","admin");p.projectPublished("tenant-a","alice","agent-a",aCtx);String aText=f.agent().getWorkspaceManager().readAgentsMd(aCtx);if(!aText.contains("A-style"))throw new AssertionError(aText);if(Files.readString(ws.resolve("tools.json")).contains("allow"))throw new AssertionError("tenant allow leaked into build-time tools.json");
 AgentBlueprint b1=bp("bp-b",1,"tenant-b","agent-b","B-style");repo.stage(b1,"builder");repo.publish("bp-b","tenant-b","admin");RuntimeContext bCtx=contexts.create("tenant-b","bob","s1","agent-b");p.projectPublished("tenant-b","bob","agent-b",bCtx);String bText=f.agent().getWorkspaceManager().readAgentsMd(bCtx);if(!bText.contains("B-style")||f.agent().getWorkspaceManager().readAgentsMd(aCtx).contains("B-style"))throw new AssertionError("tenant isolation failed");
 RuntimeService runtime=new RuntimeService(f.agent(),p,permissions);String answer=runtime.chat("tenant-a","alice","s2","agent-a","hello");if(!answer.contains("DRY_RUN_OK"))throw new AssertionError(answer);
 AgentBlueprint libOnly=new AgentBlueprint("bp-lib",1,"tenant-a","agent-lib",new AgentBlueprint.Meta("test",List.of(),"test","run-lib"),new AgentBlueprint.Prompt("# lib","# soul","# knowledge"),List.of(new AgentBlueprint.Skill("human-handoff","library","skill:human-handoff@1",null)),new AgentBlueprint.Tools(List.of("read_file","memory_search","load_skill_through_path"),List.of(),List.of()),new AgentBlueprint.RuntimeSpec("deterministic-test","USER",8000));String d1=runtime.dryRun(libOnly,"alice");String d2=runtime.dryRun(libOnly,"alice");if(!d1.contains("DRY_RUN_OK")||!d2.contains("DRY_RUN_OK"))throw new AssertionError("library-only repeat dry-run failed: "+d1+" / "+d2);RuntimeContext permissionCtx=contexts.create("tenant-a","alice","s2","agent-a");PermissionContextState permissionState=f.agent().getDelegate().getAgentState(permissionCtx).getPermissionContext();if(permissionState.isTrivial())throw new AssertionError("runtime permission context not installed");ToolBase readFile=(ToolBase)f.agent().getDelegate().getToolkit().getTool("read_file");if(new PermissionEngine(permissionState).checkPermission(readFile,Map.of("path","AGENTS.md")).block().getBehavior()!=PermissionBehavior.ALLOW)throw new AssertionError("allowed tool was not allowed by AgentScope engine");RuntimeContext deniedCtx=contexts.create("tenant-a","alice","denied","agent-a");permissions.configure("tenant-a",List.of("memory_search"),List.of("read_file"));permissions.install(f.agent(),deniedCtx,"tenant-a");PermissionContextState deniedState=f.agent().getDelegate().getAgentState(deniedCtx).getPermissionContext();if(new PermissionEngine(deniedState).checkPermission(readFile,Map.of("path","AGENTS.md")).block().getBehavior()!=PermissionBehavior.DENY)throw new AssertionError("denied tool bypassed AgentScope engine");
 AgentBlueprint v2=bp("bp-2",2,"tenant-a","agent-a","A-v2");repo.stage(v2,"builder");repo.publish("bp-2","tenant-a","admin");RuntimeContext a2=contexts.create("tenant-a","alice","s3","agent-a");p.projectPublished("tenant-a","alice","agent-a",a2);if(!f.agent().getWorkspaceManager().readAgentsMd(a2).contains("A-v2"))throw new AssertionError("hot publish failed");repo.rollback("tenant-a","agent-a",1,"admin");RuntimeContext a3=contexts.create("tenant-a","alice2","s4","agent-a");p.projectPublished("tenant-a","alice2","agent-a",a3);if(!f.agent().getWorkspaceManager().readAgentsMd(a3).contains("A-style"))throw new AssertionError("rollback failed");
 AuthService auth=new AuthService("runtime-token-0123456789","admin-token-01234567890");auth.require("Bearer runtime-token-0123456789");boolean denied=false;try{auth.requireAdmin("Bearer runtime-token-0123456789","admin");}catch(SecurityException e){denied=true;}if(!denied)throw new AssertionError("runtime token became admin via spoofed role");auth.requireAdmin("Bearer admin-token-01234567890","admin");boolean sameRejected=false;try{new AuthService("same-token-0123456789","same-token-0123456789");}catch(IllegalArgumentException e){sameRejected=true;}if(!sameRejected)throw new AssertionError("identical runtime/admin tokens accepted");boolean invalidContext=false;try{contexts.create("tenant-a","alice","../escape","agent-a");}catch(IllegalArgumentException e){invalidContext=true;}if(!invalidContext)throw new AssertionError("unsafe session id accepted");permissions.grant("tenant-a",List.of("crm_query"));if(!permissions.allowed("tenant-a","crm_query")||permissions.allowed("tenant-b","crm_query"))throw new AssertionError("tool permissions");if(repo.audit().size()!=7)throw new AssertionError(repo.audit());try(AgentFactory aware=new AgentFactory(ws,new BlueprintAwareModel())){RuntimeService probeRt=new RuntimeService(aware.agent(),new BlueprintProjector(aware.agent(),repo,permissions),permissions);String probe=probeRt.chat("tenant-a","alice","s5","agent-a","你好");if(!probe.contains("BLUEPRINT_OK")||!probe.contains("runtimeAgentId=agent-a")||probe.equals("你好")||probe.equals("DRY_RUN_OK: 你好"))throw new AssertionError("blueprint-aware stub: "+probe);}System.out.println("[PASS] singleton HarnessAgent, PUBLISHED-only projection, USER isolation, hot publish, rollback, split admin/runtime auth and permissions");}}
 private static AgentBlueprint bp(String id,int version,String client,String agent,String style){return new AgentBlueprint(id,version,client,agent,new AgentBlueprint.Meta("test",List.of(),"test","run-"+id),new AgentBlueprint.Prompt("# "+style,"# soul "+style,"# knowledge"),List.of(new AgentBlueprint.Skill("inline-help","inline",null,"---\nname: inline-help\ndescription: 当需要帮助时使用\n---\nhelp")),new AgentBlueprint.Tools(List.of("read_file","memory_search","load_skill_through_path"),List.of(),List.of(new AgentBlueprint.McpServer("crm","https://higress.local/mcp-servers/crm/mcp","streamableHttp"))),new AgentBlueprint.RuntimeSpec("deterministic-test","USER",8000));}
}
